-- Hyprland values of the {{ theme }} theme. GENERATED by `theme` from
-- ~/dotfiles/theme/templates/hypr.lua; edit that and run `theme apply`.
-- Read through lua/theme.lua by look.lua, env.lua, apps.lua and autostart.lua.
return {
    name = {{ lua(theme) }},

    -- Focused window: a grey-to-white gradient; unfocused tiles keep a visible
    -- edge (about #2e2e2e on black) without competing with it.
    active_border   = { "rgba({{ tone(0x84).a(0xaa).hexa }})", "rgba({{ tone(0xf9).a(0xaa).hexa }})" },
    inactive_border = "rgba({{ fg.a(0x2e).hexa }})",
    glow            = "rgba({{ fg.a(0x28).hexa }})",
    glow_inactive   = "rgba({{ bg.a(0x00).hexa }})",
    shadow          = "rgba({{ bg.a(0xaa).hexa }})",
    shadow_inactive = "rgba({{ bg.a(0x55).hexa }})",

    rounding         = {{ look.radius }},
    gaps_in          = {{ look.gaps_in }},
    gaps_out         = {{ look.gaps_out }},
    border_size      = {{ look.border }},
    active_opacity   = {{ look.active_opacity }},
    inactive_opacity = {{ look.inactive_opacity }},

    wallpaper    = {{ lua(asset.wallpaper) }},
    cursor_theme = {{ lua(asset.cursor_theme) }},
    cursor_size  = {{ asset.cursor_size }},
    gtk_theme    = {{ lua(asset.gtk_theme or "Current") }},
    icon_theme   = {{ lua(asset.icon_theme) }},
    color_scheme = {{ lua("prefer-dark" if dark else "prefer-light") }},
}
